-- TEST RUN exams: one short 20-question practice exam for EACH specialty (Critical Care, Perioperative,
-- Anaesthesia, Nephrology). New private-class students use it to try the Exam Room before the real mocks.
-- Open from now until 31 Dec 2026, 20 minutes, up to 3 attempts, answers shown after each question.
-- Questions are hidden exam-only copies that are NOT in any of the mock exams. Safe to run more than once.
set lock_timeout = '5s';
begin;
create temporary table tnew (paper int, n int, source text, topic text, q text, opts jsonb, ans_idx int, exp text, category text, primary key (paper, n)) on commit drop;
select (select coalesce(max(id), 0) from public.questions) + row_number() over (order by d.paper, d.n), d.topic, d.source, d.q, d.opts, d.ans_idx, d.exp, d.category, '🧪', false
from tnew d where not exists (select 1 from public.questions x where x.source = d.source and x.q = d.q);
update public.exam_exams set question_ids = (select array_agg(x.id order by d.n) from tnew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 1), instructions = 'TEST RUN for Critical Care Nursing. 20 practice questions so you can see how the Nursing Exam Room works before the real mock exams. The real exams cover your whole curriculum with standard council-style questions. You have 20 minutes and up to 3 attempts.', specialty = 'ccn', attempts_allowed = 3,
       starts_at = timestamptz '2026-11-01 00:00:00+01', ends_at = timestamptz '2026-12-31 23:55:00+01', duration_minutes = 20 where title = 'Test Run — Critical Care Nursing (20 Questions)';
                               max_warnings, shuffle, all_candidates, attempts_allowed, proctor_level, specialty)
select 'Test Run — Critical Care Nursing (20 Questions)', 'TEST RUN for Critical Care Nursing. 20 practice questions so you can see how the Nursing Exam Room works before the real mock exams. The real exams cover your whole curriculum with standard council-style questions. You have 20 minutes and up to 3 attempts.', timestamptz '2026-11-01 00:00:00+01', timestamptz '2026-12-31 23:55:00+01', 20, (select array_agg(x.id order by d.n) from tnew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 1),
       true, true, 100, true, true, 3, 'relaxed', 'ccn'
where not exists (select 1 from public.exam_exams where title = 'Test Run — Critical Care Nursing (20 Questions)');
update public.exam_exams set question_ids = (select array_agg(x.id order by d.n) from tnew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 2), instructions = 'TEST RUN for Perioperative Nursing. 20 practice questions so you can see how the Nursing Exam Room works before the real mock exams. The real exams cover your whole curriculum with standard council-style questions. You have 20 minutes and up to 3 attempts.', specialty = 'periop', attempts_allowed = 3,
       starts_at = timestamptz '2026-11-01 00:00:00+01', ends_at = timestamptz '2026-12-31 23:55:00+01', duration_minutes = 20 where title = 'Test Run — Perioperative Nursing (20 Questions)';
                               max_warnings, shuffle, all_candidates, attempts_allowed, proctor_level, specialty)
select 'Test Run — Perioperative Nursing (20 Questions)', 'TEST RUN for Perioperative Nursing. 20 practice questions so you can see how the Nursing Exam Room works before the real mock exams. The real exams cover your whole curriculum with standard council-style questions. You have 20 minutes and up to 3 attempts.', timestamptz '2026-11-01 00:00:00+01', timestamptz '2026-12-31 23:55:00+01', 20, (select array_agg(x.id order by d.n) from tnew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 2),
       true, true, 100, true, true, 3, 'relaxed', 'periop'
where not exists (select 1 from public.exam_exams where title = 'Test Run — Perioperative Nursing (20 Questions)');
update public.exam_exams set question_ids = (select array_agg(x.id order by d.n) from tnew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 3), instructions = 'TEST RUN for Anaesthesia Nursing. 20 practice questions so you can see how the Nursing Exam Room works before the real mock exams. The real exams cover your whole curriculum with standard council-style questions. You have 20 minutes and up to 3 attempts.', specialty = 'anaes', attempts_allowed = 3,
       starts_at = timestamptz '2026-11-01 00:00:00+01', ends_at = timestamptz '2026-12-31 23:55:00+01', duration_minutes = 20 where title = 'Test Run — Anaesthesia Nursing (20 Questions)';
                               max_warnings, shuffle, all_candidates, attempts_allowed, proctor_level, specialty)
select 'Test Run — Anaesthesia Nursing (20 Questions)', 'TEST RUN for Anaesthesia Nursing. 20 practice questions so you can see how the Nursing Exam Room works before the real mock exams. The real exams cover your whole curriculum with standard council-style questions. You have 20 minutes and up to 3 attempts.', timestamptz '2026-11-01 00:00:00+01', timestamptz '2026-12-31 23:55:00+01', 20, (select array_agg(x.id order by d.n) from tnew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 3),
       true, true, 100, true, true, 3, 'relaxed', 'anaes'
where not exists (select 1 from public.exam_exams where title = 'Test Run — Anaesthesia Nursing (20 Questions)');
update public.exam_exams set question_ids = (select array_agg(x.id order by d.n) from tnew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 4), instructions = 'TEST RUN for Nephrology Nursing. 20 practice questions so you can see how the Nursing Exam Room works before the real mock exams. The real exams cover your whole curriculum with standard council-style questions. You have 20 minutes and up to 3 attempts.', specialty = 'neph', attempts_allowed = 3,
       starts_at = timestamptz '2026-11-01 00:00:00+01', ends_at = timestamptz '2026-12-31 23:55:00+01', duration_minutes = 20 where title = 'Test Run — Nephrology Nursing (20 Questions)';
                               max_warnings, shuffle, all_candidates, attempts_allowed, proctor_level, specialty)
select 'Test Run — Nephrology Nursing (20 Questions)', 'TEST RUN for Nephrology Nursing. 20 practice questions so you can see how the Nursing Exam Room works before the real mock exams. The real exams cover your whole curriculum with standard council-style questions. You have 20 minutes and up to 3 attempts.', timestamptz '2026-11-01 00:00:00+01', timestamptz '2026-12-31 23:55:00+01', 20, (select array_agg(x.id order by d.n) from tnew d join public.questions x on x.source = d.source and x.q = d.q where d.paper = 4),
       true, true, 100, true, true, 3, 'relaxed', 'neph'
where not exists (select 1 from public.exam_exams where title = 'Test Run — Nephrology Nursing (20 Questions)');
select title, specialty, cardinality(question_ids) as questions, starts_at, ends_at, attempts_allowed from public.exam_exams where title like 'Test Run — %' order by specialty;
commit;
